	SM ($0080), R0
	MOVE R14, R1
	IBT R0, #$11
	CMODE
	IBT R2, #$00
	IWT R4, #$0F0F
	GETB
	ADD R0
	ADD R0
	ADD R0
	TO R6
	ADD R0
	LINK #4
	IWT R15, #CODE_0A81B3 : GETB
	ROL
	OR R6
	TO R6
	AND R4
	GETB
	ADD R0
	ADD R0
	ADD R0
	TO R7
	ADD R0
	LINK #4
	IWT R15, #CODE_0A81B3 : GETB
	ROL
	OR R7
	TO R7
	AND R4
	GETB
	ADD R0
	ADD R0
	ADD R0
	TO R8
	ADD R0
	LINK #4
	IWT R15, #CODE_0A81B3 : GETB
	ROL
	OR R8
	TO R8
	AND R4
	GETB
	TO R9
	AND R4
	SUB R0
	IBT R1, #$00
	IBT R12, #$40
	CACHE
	MOVE R13, R15
	STW (R1)
	INC R1
	LOOP : INC R1
	DEC R1
	LINK #4
	IWT R15, #CODE_0A81B3 : GETB
	IBT R10, #$05
	LSR
	LSR
	IWT R15, #CODE_0A8116 : LSR

