	IBT R0, #(DATA_0ACECB-$02)>>16
	ROMB
	IBT R1, #$00
	IBT R12, #$28
	CACHE
	MOVE R13, R15
	IWT R0, #$0EC3
	ADD R1
	LDB (R0)
	MOVES R2, R0
	BEQ CODE_0AD00D : NOP
	IWT R0, #$1820
	ADD R1
	LDW (R0)
	BIC #1
	SBK
	IBT R2, #$00
