	IWT R0, #$0EC2
	ADD R1
	FROM R2
	STW (R0)
	IWT R0, #$0EC0
	ADD R1
	LDW (R0)
	SUB #14
	BCC CODE_0AD07E : NOP
	IWT R0, #$0F62
	ADD R1
	LDW (R0)
	IBT R7, #$1F
	AND R7
	BEQ CODE_0AD07E : ADD R0
	IWT R14, #DATA_0ACECB-$02
	TO R14
	ADD R14
	IWT R0, #$10A2
	ADD R1
	TO R9
	LDW (R0)
	TO R7
	GETB
	INC R14
	IWT R0, #$1142
	ADD R1
	TO R10
	LDW (R0)
	IWT R0, #$16E0
	ADD R1
	LDW (R0)
	TO R10
	ADD R10
	GETB
	ADD R0
	IWT R14, #DATA_0ACF09
	TO R14
	ADD R14
	FROM R7
	ADD R7
	ADD R7
	INC R0
	TO R15
	ADD R15 : db $FF

